CREATE TABLE openalex.funders.funder_id (
  id_type STRING NOT NULL, id_value STRING NOT NULL, funder_id BIGINT NOT NULL, origin_funder_id BIGINT, is_primary BOOLEAN,
  source STRING, added_at TIMESTAMP, run_id STRING) USING DELTA;

CREATE TABLE openalex.funders.funder_decision (
  run_id STRING NOT NULL, decided_at TIMESTAMP, source STRING, source_key STRING, action STRING NOT NULL, funder_id BIGINT,
  ror_rid STRING, fundref STRING, display_name STRING, country STRING, evidence STRING) USING DELTA;

-- CREATE (no REPLACE) makes this release immutable; use a fresh release id to restage.
CREATE TABLE openalex.funders.nm1013_integrated_catalogue_before AS SELECT * FROM openalex.funders.funders;
CREATE TABLE openalex.funders.nm1013_integrated_registry_before AS SELECT * FROM openalex.funders.funder;
CREATE TABLE openalex.funders.nm1013_integrated_identifiers_before AS SELECT * FROM openalex.funders.funder_id;

SELECT assert_true(count(*)=0 AND count_if(l.funder_id IS NULL OR w.funder_id IS NULL OR l.merge_into_id IS NOT NULL OR w.merge_into_id IS NOT NULL OR (l.ror_id IS NOT NULL AND w.ror_id IS NOT NULL AND l.ror_id<>w.ror_id))=0,'merge preconditions changed')
FROM openalex.funders.nm1013_integrated_merges m
LEFT JOIN openalex.funders.nm1013_integrated_catalogue_before l ON l.funder_id=m.loser_id
LEFT JOIN openalex.funders.nm1013_integrated_catalogue_before w ON w.funder_id=m.survivor_id;
SELECT assert_true(count(*)=0,'incoming redirects require renewed merge review') FROM openalex.funders.nm1013_integrated_catalogue_before f JOIN openalex.funders.nm1013_integrated_merges m ON f.merge_into_id=m.loser_id;
CREATE TABLE openalex.funders.nm1013_integrated_catalogue_after AS
SELECT f.* EXCEPT(merge_into_id),coalesce(m.survivor_id,f.merge_into_id) merge_into_id
FROM openalex.funders.nm1013_integrated_catalogue_before f
LEFT JOIN openalex.funders.nm1013_integrated_merges m ON m.loser_id=f.funder_id;
CREATE TABLE openalex.funders.nm1013_integrated_identifiers AS
SELECT 'ror' id_type,ror_id id_value,funder_id,funder_id origin_funder_id
FROM openalex.funders.nm1013_integrated_catalogue_before WHERE ror_id IS NOT NULL;
CREATE TABLE openalex.funders.nm1013_integrated_registry_after AS SELECT f.funder_id AS funder_id,CASE WHEN m.loser_id IS NOT NULL THEN 'merged' ELSE f.status END AS status,coalesce(m.survivor_id,f.merged_into_id) AS merged_into_id,f.ror_id AS ror_id,f.ror_primary AS ror_primary,f.parent_id AS parent_id,f.display_name AS display_name,f.alt_names AS alt_names,f.country_code AS country_code,f.homepage_url AS homepage_url,f.wikidata_id AS wikidata_id,f.description AS description,f.image_url AS image_url,f.image_thumbnail_url AS image_thumbnail_url,f.created_date AS created_date,CASE WHEN m.loser_id IS NOT NULL THEN current_timestamp() ELSE f.updated_date END AS updated_date,f.created_by AS created_by,CASE WHEN m.loser_id IS NOT NULL THEN 'openalex.funders.nm1013_integrated_' ELSE f.run_id END AS run_id,f.mint_key AS mint_key FROM openalex.funders.nm1013_integrated_registry_before f LEFT JOIN openalex.funders.nm1013_integrated_merges m ON f.funder_id=m.loser_id OR f.merged_into_id=m.loser_id;
CREATE TABLE openalex.funders.nm1013_integrated_identifiers_after AS SELECT f.id_type AS id_type,f.id_value AS id_value,coalesce(m.survivor_id,f.funder_id) AS funder_id,f.origin_funder_id AS origin_funder_id,f.is_primary AS is_primary,f.source AS source,f.added_at AS added_at,CASE WHEN m.loser_id IS NOT NULL THEN 'openalex.funders.nm1013_integrated_' ELSE f.run_id END AS run_id FROM openalex.funders.nm1013_integrated_identifiers_before f LEFT JOIN openalex.funders.nm1013_integrated_merges m ON f.funder_id=m.loser_id AND f.id_type NOT IN ('name','ror_cleared');
SELECT assert_true(count(*)=0,'duplicate identifier key') FROM (SELECT id_type,id_value FROM openalex.funders.nm1013_integrated_identifiers_before GROUP BY ALL HAVING count(*)<>1);

CREATE TABLE openalex.funders.nm1013_integrated_lookup AS
SELECT l.*, 'openalex.funders.nm1013_integrated_' release_id,s.catalogue_signature FROM openalex.funders.nm1013_integrated_lookup_rows l
CROSS JOIN (SELECT concat(count(*), ':', cast(sum(cast(xxhash64(funder_id,display_name,alternate_titles,ror_id,doi,crossref_id,merge_into_id) AS DECIMAL(38,0))) AS STRING)) catalogue_signature FROM openalex.funders.nm1013_integrated_catalogue_after) s;
SELECT assert_true((SELECT count(*) FROM openalex.funders.nm1013_integrated_aliases)=204,'alias count'),
 assert_true((SELECT count(*) FROM (SELECT rule,name_key FROM openalex.funders.nm1013_integrated_lookup GROUP BY ALL HAVING count(*)<>1))=0,'ambiguous lookup');
SELECT assert_true(count(*)=0,'alias target absent from approved catalogue or lookup')
FROM openalex.funders.nm1013_integrated_aliases a
LEFT JOIN openalex.funders.nm1013_integrated_catalogue_after f ON f.funder_id=a.funder_id
LEFT JOIN openalex.funders.nm1013_integrated_lookup l ON l.rule=a.rule AND l.name_key=a.name_key AND l.funder_id=coalesce(f.merge_into_id,f.funder_id)
WHERE f.funder_id IS NULL OR l.funder_id IS NULL;

-- Readers remain on main until the last publication statement. Operator keeps
-- their schedules paused during activation and restores them for the next night.
SELECT assert_true((SELECT count(*) FROM (
 (SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.funders EXCEPT ALL SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.nm1013_integrated_catalogue_before)
 UNION ALL (SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.nm1013_integrated_catalogue_before EXCEPT ALL SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.funders)
))=0,'catalogue changed since stage: restage and reapprove');
-- No-merge switch: registry, identifiers and compat must remain exact.
SELECT assert_true((SELECT count(*) FROM (
 (SELECT * FROM openalex.funders.funder EXCEPT ALL SELECT * FROM openalex.funders.nm1013_integrated_registry_before)
 UNION ALL (SELECT * FROM openalex.funders.nm1013_integrated_registry_before EXCEPT ALL SELECT * FROM openalex.funders.funder)))=0,'registry changed since stage');
SELECT assert_true((SELECT count(*) FROM (
 (SELECT * FROM openalex.funders.funder_id EXCEPT ALL SELECT * FROM openalex.funders.nm1013_integrated_identifiers_before)
 UNION ALL (SELECT * FROM openalex.funders.nm1013_integrated_identifiers_before EXCEPT ALL SELECT * FROM openalex.funders.funder_id)))=0,'identifier ownership changed since stage');
SELECT assert_true(count(*)=0 AND count_if(l.status<>'active' OR l.merged_into_id IS NOT NULL OR w.status<>'active' OR l.funder_id IS NULL OR w.funder_id IS NULL)=0,'registry merge preconditions')
FROM openalex.funders.nm1013_integrated_merges m
LEFT JOIN openalex.funders.funder l ON l.funder_id=m.loser_id
LEFT JOIN openalex.funders.funder w ON w.funder_id=m.survivor_id;
SELECT assert_true((SELECT count(*) FROM (
 (SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.funders EXCEPT ALL SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.nm1013_integrated_catalogue_after)
 UNION ALL (SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.nm1013_integrated_catalogue_after EXCEPT ALL SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.funders)
))=0,'catalogue publication mismatch: keep readers paused');
SELECT assert_true(count(*)=0,'funder activation mismatch: keep readers paused') FROM ((SELECT * FROM openalex.funders.funder EXCEPT ALL SELECT * FROM openalex.funders.nm1013_integrated_registry_after) UNION ALL (SELECT * FROM openalex.funders.nm1013_integrated_registry_after EXCEPT ALL SELECT * FROM openalex.funders.funder));
SELECT assert_true(count(*)=0,'funder_id activation mismatch: keep readers paused') FROM ((SELECT * FROM openalex.funders.funder_id EXCEPT ALL SELECT * FROM openalex.funders.nm1013_integrated_identifiers_after) UNION ALL (SELECT * FROM openalex.funders.nm1013_integrated_identifiers_after EXCEPT ALL SELECT * FROM openalex.funders.funder_id));
CREATE OR REPLACE TABLE openalex.funders.funder_name_lookup AS SELECT * FROM openalex.funders.nm1013_integrated_lookup;
